type Analytics = {
  totalViews: number
  activeUsers: number
  conversionRate: number
}

type NotificationItem = {
  id: string
  message: string
  read: boolean
}

type Notifications = {
  items: NotificationItem[]
}

type Settings = {
  theme: string
  emailDigest: boolean
  timezone: string
}

function getServerBaseUrl(): string {
  if (process.env.VERCEL_URL) {
    return `https://${process.env.VERCEL_URL}`
  }
  return `http://127.0.0.1:${process.env.PORT ?? '3000'}`
}

async function fetchJson<T>(url: string): Promise<T> {
  const res = await fetch(url, { cache: 'no-store' })
  if (!res.ok) {
    throw new Error(`Failed to fetch ${url}: ${res.status}`)
  }
  return res.json() as Promise<T>
}

async function getDashboardData() {
  const base = getServerBaseUrl()
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetchJson<Analytics>(`${base}/api/analytics`),
      fetchJson<Notifications>(`${base}/api/notifications`),
      fetchJson<Settings>(`${base}/api/settings`),
    ])

    return { analytics, notifications, settings }
  } catch {
    return {
      analytics: {
        totalViews: 0,
        activeUsers: 0,
        conversionRate: 0,
      },
      notifications: { items: [] as NotificationItem[] },
      settings: {
        theme: 'system',
        emailDigest: true,
        timezone: 'UTC',
      },
    }
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData()
  const unreadCount = notifications.items.filter((n) => !n.read).length

  return (
    <div>
      <h2>Dashboard Content</h2>

      <section aria-labelledby="analytics-heading">
        <h3 id="analytics-heading">Analytics</h3>
        <ul>
          <li>Total views: {analytics.totalViews.toLocaleString()}</li>
          <li>Active users: {analytics.activeUsers.toLocaleString()}</li>
          <li>Conversion rate: {analytics.conversionRate}%</li>
        </ul>
      </section>

      <section aria-labelledby="notifications-heading">
        <h3 id="notifications-heading">
          Notifications
          {unreadCount > 0 ? ` (${unreadCount} unread)` : ''}
        </h3>
        {notifications.items.length === 0 ? (
          <p>No notifications.</p>
        ) : (
          <ul>
            {notifications.items.map((n) => (
              <li key={n.id}>
                {n.read ? '' : <strong>(New) </strong>}
                {n.message}
              </li>
            ))}
          </ul>
        )}
      </section>

      <section aria-labelledby="settings-heading">
        <h3 id="settings-heading">Settings</h3>
        <ul>
          <li>Theme: {settings.theme}</li>
          <li>Email digest: {settings.emailDigest ? 'On' : 'Off'}</li>
          <li>Timezone: {settings.timezone}</li>
        </ul>
      </section>
    </div>
  )
}

